routes = optimization.get("routes", [])
for route in routes:
    vehicle_id = route.get("vehicleId") or route.get("vehicle_id")
    if vehicle_id is None:
        continue

    emission_response = session.post(
        f"{BASE_URL}/emissions",
        json={
            "vehicleId": vehicle_id,
            "route": route,
            "emissionData": route.get("emissionData", route.get("emissions")),
