import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
TOKEN = os.getenv("API_TOKEN")

session = requests.Session()
session.headers.update({"Accept": "application/json"})
if TOKEN:
    session.headers["Authorization"] = f"Bearer {TOKEN}"


def request(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    return response


# Update the inventory manager's contact information.
contact_info = {
    "name": os.getenv("INVENTORY_MANAGER_NAME"),
    "email": os.getenv("INVENTORY_MANAGER_EMAIL"),
    "phone": os.getenv("INVENTORY_MANAGER_PHONE"),
}
contact_info = {key: value for key, value in contact_info.items() if value}
request("PATCH", "/update_contact_info", json=contact_info)

# Submit responses to the questionnaire evaluating inventory-system efficiency.
questionnaire_id = os.getenv("QUESTIONNAIRE_ID")
if not questionnaire_id:
    raise ValueError("Set QUESTIONNAIRE_ID to the questionnaire's identifier.")

responses_payload = {
    "questionnaireId": questionnaire_id,
    "responses": [
        {
            "questionId": os.getenv("EFFICIENCY_QUESTION_ID", "inventory-system-efficiency"),
            "answer": os.getenv("EFFICIENCY_ANSWER", ""),
        }
    ],
}
request("POST", "/responses", json=responses_payload)

# Retrieve medications below the low-stock threshold.
low_stock_response = request("GET", "/inventory/low-stock")
low_stock_data = low_stock_response.json()
medications = (
    low_stock_data
    if isinstance(low_stock_data, list)
    else low_stock_data.get("medications", [])
)

# Create an order to replenish the low-stock medications.
if medications:
    order_items = [
        {
            "medicationId": medication.get("medicationId", medication.get("id")),
            "quantity": int(medication.get("reorderQuantity", 1)),
        }
        for medication in medications
    ]
    request("POST", "/orders/new", json={"medications": order_items})

# Delete medications explicitly marked for removal.
medications_to_remove = [
    medication
    for medication in medications
    if medication.get("markedForRemoval") is True
    or medication.get("status") == "marked_for_removal"
]
for medication in medications_to_remove:
    medication_id = medication.get("medicationId", medication.get("id"))
    if medication_id is not None:
        request("DELETE", f"/inventory/remove/{medication_id}")

