import requests

BASE_URL = "https://api.socbench.example"

metrics_response = requests.get(f"{BASE_URL}/performance")
metrics_response.raise_for_status()
metrics = metrics_response.json()

# Identify systems whose reported performance indicates degradation.
underperforming = []
if isinstance(metrics, list):
    records = metrics
elif isinstance(metrics, dict):
    records = metrics.get("resources", metrics.get("metrics", []))
    if isinstance(records, dict):
        records = [records]
else:
    records = []

for record in records:
    if not isinstance(record, dict):
        continue

    status = str(record.get("status", "")).lower()
    degraded = record.get("degraded", False) or record.get("underperforming", False)
    if status in {"degraded", "underperforming", "poor", "critical"} or degraded:
        underperforming.append(record)

if underperforming:
    alert_payload = {
        "title": "Degraded resource performance detected",
        "description": "The following configured systems are exhibiting degraded performance: "
        + ", ".join(
            str(item.get("name", item.get("id", "unknown resource")))
            for item in underperforming
        ),
        "resources": underperforming,
        "team": "relevant team",
    }
    alert_response = requests.post(
        f"{BASE_URL}/alert",
        json=alert_payload,
        headers={"Content-Type": "application/json"},
    )
    alert_response.raise_for_status()

